using System.Diagnostics;
using System.Text;
using Puck.Abstractions;

namespace Puck.Assets;

/// <summary>A content-addressed cache of generated bytes. Every read checks the payload's integrity; a missing,
/// corrupt or unreadable entry derives again. Cache storage failures never refuse the derived product.</summary>
public sealed class DerivedBytes {
    /// <summary>Optional host-selected cache root; all products otherwise use the per-user derived directory.</summary>
    public static string? DefaultDirectory { get; set; }
    private readonly CodeClosure m_code;
    private readonly string m_name;
    private long m_hits;
    private long m_misses;

    /// <summary>Creates a cache owner with its production deriving roots.</summary>
    /// <param name="name">The diagnostic owner name.</param>
    /// <param name="roots">Assembly, full type and method roots.</param>
    public DerivedBytes(string name, IReadOnlyList<(string Assembly, string Type, string? Method)> roots) {
        m_name = name;
        m_code = CodeClosure.Of(directory: AppContext.BaseDirectory, roots: roots,
            stopTypes: new HashSet<string>(collection: [typeof(DerivedBytes).FullName!, typeof(CodeClosure).FullName!], comparer: StringComparer.Ordinal));
    }

    /// <summary>Gets bytes derived from explicit inputs and the deriving code, including applied code updates.</summary>
    /// <param name="inputs">The canonical inputs to the generator.</param>
    /// <param name="derive">The derivation of those inputs.</param>
    /// <param name="directory">An explicit cache directory, or the per-user derived cache.</param>
    /// <returns>A private byte array.</returns>
    public byte[] Get(string inputs, Func<byte[]> derive, string? directory = null) =>
        GetCore(inputs, derive, directory, null, null);

    /// <summary>Reads a toolchain product, or derives it using the named toolchain. A shipping cache carries
    /// compiler provenance under the current source/code identity, so its reader needs no compiler installed.</summary>
    /// <param name="inputs">Source and build-option identity.</param>
    /// <param name="toolchain">Discovers and identifies the compiler used on a local miss.</param>
    /// <param name="derive">Builds the bytes with that compiler.</param>
    /// <param name="directory">Local cache directory, or the per-user derived cache.</param>
    /// <param name="packageDirectory">Shipping cache to read, or populate when prewarming.</param>
    /// <param name="prewarm">Whether to populate the shipping cache from a live compiler.</param>
    /// <returns>Verified cached or freshly derived bytes.</returns>
    public byte[] GetToolchain(string inputs, Func<string> toolchain, Func<byte[]> derive,
        string? directory = null, string? packageDirectory = null, bool prewarm = false) =>
        GetCore(inputs, derive, directory, toolchain, packageDirectory, prewarm);

    private byte[] GetCore(string inputs, Func<byte[]> derive, string? directory, Func<string>? toolchain,
        string? packageDirectory, bool prewarm = false) {
        var source = $"{m_name}\n{m_code.Hash:x32}\n{CodeRevision.AppliedTo(reads: m_code.Reads)}\n{inputs}";
        var sourcePin = ContentPin.Compute(content: Encoding.UTF8.GetBytes(source));
        // Provenance is a content-addressed shipping input, never an expected output or a repository ledger.
        ContentAddressedStore? package = null;
        string[] packages = packageDirectory is not null ? [packageDirectory] : toolchain is not null
            ? [Path.Combine(AppContext.BaseDirectory, "derived"), Path.Combine(Environment.CurrentDirectory, "derived")] : [];
        foreach (var candidate in packages.Where(candidate => prewarm || Directory.Exists(candidate))) {
            try {
                package = new ContentAddressedStore(candidate);
                if (!prewarm && package.TryResolveDerived($"{m_name}-toolchain", sourcePin, out var compilerPin)
                    && package.TryGet(compilerPin, out var compiler)) {
                    var packagedIdentity = ContentPin.Compute(Encoding.UTF8.GetBytes($"{source}\n{Encoding.UTF8.GetString(compiler)}"));
                    if (package.TryResolveDerived(m_name, packagedIdentity, out var productPin) && package.TryGet(productPin, out var product)) {
                        Hit(inputs);
                        return product;
                    }
                }
            } catch (Exception exception) when (exception is IOException or UnauthorizedAccessException) { }
        }
        var compilerIdentity = toolchain?.Invoke();
        var identity = ContentPin.Compute(content: Encoding.UTF8.GetBytes(s: toolchain is null ? source : $"{source}\n{compilerIdentity}"));
        ContentAddressedStore? store = null;
        try {
            store = new ContentAddressedStore(root: directory ?? DefaultDirectory ?? PuckUserDirectory.Resolve(name: "derived"), retention: new CacheBound(MaxBytes: 64L << 20, MaxEntries: 1024));
            if (store.TryResolveDerived(kind: m_name, inputHash: identity, hash: out var pin) && store.TryGet(pin: pin, content: out var entry)) {
                if (prewarm) { Publish(entry); }
                Hit(inputs);
                return entry;
            }
        } catch (Exception exception) when (exception is IOException or UnauthorizedAccessException) { }
        var watch = Stopwatch.StartNew();
        var bytes = derive();
        try { store?.SetDerived(kind: m_name, inputHash: identity, outputHash: store.Put(content: bytes)); }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException) { }
        if (prewarm) { Publish(bytes); }
        Console.Error.WriteLine(value: $"[derived] {m_name} {inputs}: miss; hits={Interlocked.Read(location: ref m_hits)} misses={Interlocked.Increment(location: ref m_misses)} deriveMs={watch.Elapsed.TotalMilliseconds:F3}");
        return bytes;

        void Publish(byte[] content) {
            // Shipping is an explicit write: failure must fail packaging, not claim a prewarmed player.
            if (package is null) { throw new IOException($"Cannot write shipping cache {packageDirectory}."); }
            package.SetDerived(m_name, identity, package.Put(content));
            package.SetDerived($"{m_name}-toolchain", sourcePin, package.Put(Encoding.UTF8.GetBytes(compilerIdentity!)));
        }
    }

    private void Hit(string inputs) => Console.Error.WriteLine(value: $"[derived] {m_name} {inputs}: hit; hits={Interlocked.Increment(location: ref m_hits)} misses={Interlocked.Read(location: ref m_misses)}");
}
